const waveMap = {
  'glassy swell': { amp: 10, freq: 0.005, snap: 0 },
  'gentle ripples': { amp: 15, freq: 0.01, snap: 0 },
  'undulating surge': { amp: 25, freq: 0.015, snap: 0.1 },
  'choppy chop': { amp: 35, freq: 0.02, snap: 0.3 },
  'turbulent squall': { amp: 50, freq: 0.025, snap: 0.6 },
  'cavitation shear': { amp: 70, freq: 0.03, snap: 1.0 },
  'vortex snap': { amp: 90, freq: 0.035, snap: 1.5 }
};

const refMap = {
  'air boundary': 1.05,
  'thin saline': 1.2,
  'clear water': 1.33,
  'dense glycerin': 1.47,
  'heavy flint glass': 1.65,
  'diamond shear': 2.4
};

const focalMap = {
  'shallow bed': 350,
  'near focal plane': 450,
  'caustic cusp': 550,
  'deep trench': 650,
  'abyssal floor': 720,
  'infinite sink': 780
};

const chromMap = {
  'achromatic silver': 0.0,
  'subtle fringe': 0.01,
  'prism flare': 0.03,
  'spectral separation': 0.06,
  'tri-colour split': 0.1,
  'hyper-dispersive rainbow': 0.15
};

const densMap = {
  'sparse filaments': { count: 24, w: 1.0, a: 10 },
  'ribbon warp': { count: 48, w: 0.8, a: 8 },
  'fine lattice': { count: 80, w: 0.7, a: 6 },
  'dense sheet': { count: 120, w: 0.6, a: 5 },
  'volumetric curtain': { count: 160, w: 0.5, a: 4 },
  'blinding mesh': { count: 200, w: 0.4, a: 3 }
};

p.setup = function() {
  p.createCanvas(800, 800);
  p.pixelDensity(1);
};

p.draw = function() {
  p.background(0);
  const ctx = p.drawingContext;
  ctx.globalCompositeOperation = 'lighter';

  const wave = waveMap[p.getSynthVar('wave_turbulence') || 'glassy swell'];
  const baseN2 = refMap[p.getSynthVar('refractive_index') || 'air boundary'];
  const floorY = focalMap[p.getSynthVar('focal_depth') || 'shallow bed'];
  const split = chromMap[p.getSynthVar('chromatic_split') || 'achromatic silver'];
  const dens = densMap[p.getSynthVar('ray_density') || 'sparse filaments'];

  const t = p.frameCount * 0.02;

  const getH = (x) => {
    let base = p.sin(x * wave.freq + t) * wave.amp;
    base += p.sin(x * wave.freq * 2.3 - t * 1.5) * (wave.amp * 0.5);
    if (wave.snap > 0) {
      const cav = p.sin(x * wave.freq * 0.5 + t * 2.0);
      const snapPhase = p.pow(p.abs(p.sin(x * wave.freq * 3.1 - t * 3.0)), 8.0);
      base -= snapPhase * wave.amp * wave.snap * (cav > 0 ? 1 : -1);
    }
    return 150 + base;
  };

  p.stroke(40, 40, 40);
  p.strokeWeight(dens.w);
  ctx.beginPath();
  for (let i = 0; i < dens.count; i++) {
    const x = p.map(i, 0, dens.count - 1, 10, 790);
    ctx.moveTo(x, 0);
    ctx.lineTo(x, getH(x));
  }
  ctx.stroke();

  const colors = [
    { c: [255, 50, 50], disp: -split },
    { c: [50, 255, 50], disp: 0 },
    { c: [50, 50, 255], disp: split }
  ];

  for (let col of colors) {
    let n2 = baseN2 + col.disp;
    if (n2 < 1.01) n2 = 1.01;
    const eta = 1.0 / n2;

    p.stroke(col.c[0], col.c[1], col.c[2], dens.a);
    p.strokeWeight(dens.w);
    ctx.beginPath();

    for (let i = 0; i < dens.count; i++) {
      const x = p.map(i, 0, dens.count - 1, 10, 790);
      const sy = getH(x);

      const dx = 1.0;
      const dy = getH(x + dx) - getH(x - dx);

      const len = p.sqrt(dy * dy + 4.0);
      const Nx = -dy / len;
      const Ny = -2.0 / len; 

      let Ix = (400 - x) / floorY;
      let Iy = 1.0;
      let iLen = p.sqrt(Ix * Ix + Iy * Iy);
      Ix /= iLen;
      Iy /= iLen;

      let cosI = -(Nx * Ix + Ny * Iy);
      if (cosI < 0) cosI = 0; 

      const sinT2 = eta * eta * (1.0 - cosI * cosI);
      let Tx, Ty;
      let dist = 1500;

      if (sinT2 > 1.0) {
        Tx = Ix + 2.0 * cosI * Nx;
        Ty = Iy + 2.0 * cosI * Ny;
      } else {
        const cosT = p.sqrt(1.0 - sinT2);
        Tx = eta * Ix + (eta * cosI - cosT) * Nx;
        Ty = eta * Iy + (eta * cosI - cosT) * Ny;
      }

      if (Ty > 0.001) {
        dist = (800 - sy) / Ty;
      } else if (Ty < -0.001) {
        dist = -sy / Ty;
      }

      ctx.moveTo(x, sy);
      ctx.lineTo(x + Tx * dist, sy + Ty * dist);
    }
    ctx.stroke();
  }
};
